import puppeteer from 'puppeteer-core';
const b = await puppeteer.launch({executablePath:'/usr/bin/google-chrome', args:['--no-sandbox','--disable-gpu'], headless:'new'});
const p = await b.newPage();
await p.setViewport({width:520, height:800});
const errors = [];
p.on('pageerror', e => errors.push('pageerror: '+e.message));
p.on('console', m => { if(m.type()==='error') errors.push('console: '+m.text()); });
await p.goto('http://127.0.0.1:8901/index.html', {waitUntil:'networkidle0'});
await p.screenshot({path:'/tmp/mac-menu2.png'});
// start game and play a bit
await p.click('#startBtn');
await new Promise(r=>setTimeout(r,3500));
// move a bit
await p.keyboard.press('ArrowLeft');
await new Promise(r=>setTimeout(r,400));
await p.keyboard.press('ArrowRight');
await new Promise(r=>setTimeout(r,1200));
const st = await p.evaluate(()=>({state:window.__mac.state, score:window.__mac.score, time:document.getElementById('time').textContent}));
console.log('STATE', JSON.stringify(st));
console.log('ERRORS', errors.length ? errors.join('\n') : 'none');
await p.screenshot({path:'/tmp/mac-play2.png'});
await b.close();
EOF
